def _parameter(
    name: str,
    value: float,
    unit: str,
    group: str,
    classification: str,
    description: str,
    notes: str = "",
) -> ParameterDefinition:
    return ParameterDefinition(
        name=name,
        value=float(value),
        unit=unit,
        group=group,  # type: ignore[arg-type]
        classification=classification,  # type: ignore[arg-type]
        description=description,
        source=PARAMETER_SOURCE,
        notes=notes,
    )


